INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (163, 431, 'BOPP color printed film', '../upload/image/20211220/20211220211501_55505.jpg', '<p>BOPP color printed film<br/> 1.<br/> BOPP color (logo) printed film in jumbo roll .&nbsp;<br/> thickness : 20UM,25UM ,30UM,35UM,40UM<br/> color : red ,pink ,green,white,purple,bule ,light colors ,golden or printed customer''s own colored logos <br/> width : 350MM/400MM/500MM/600MM/700MM/800MM/1000MM<br/> length : 1000M ,3000M,4000M,6000M&nbsp;<br/> printed sides : one surface printed ( printed on the corona treated side) ,Or printed twice on the same&nbsp;side ( printed on the&nbsp; corona treated side once with one color , then printed on the&nbsp;same corona treated side with one other different color again , then can get the two color on the&nbsp;double sides&nbsp;&nbsp;)<br/> inner core :1.5 inch 1.8 inch ,2 inch ,3 inch,6 inch<br/> package : Standard exporting package ( with cartons and pallets ).<br/> logo designs: offered by customer or use our maintain designs .<br/> 2.<br/> BOPP color (logo) printed film in&nbsp;mini-smaller roll .&nbsp;<br/> thickness : 20UM,25UM ,30UM,35UM,40UM<br/> color : red ,pink ,green,white,purple,bule ,light colors ,golden or printed customer''s own colored logos <br/> width : 350MM/400MM/500MM/600MM/700MM/800MM/1000MM<br/> length : 15M,30M,60M,100M,120M,200M,500M,1000M<br/> printed sides : one surface printed ( printed on the corona treated side) ,Or printed twice on the same&nbsp;side ( printed on the&nbsp; corona treated side once with one color , then printed on the&nbsp;same corona treated side with one other different color again , then can get the two color on the&nbsp;double sides&nbsp;&nbsp;)<br/> inner core :1.5 inch 1.8 inch ,2 inch <br/> package : Standard exporting package ( with cartons and pallets ).<br/> logo designs: offered by customer or use our maintain designs .<br/> 3.<br/> BOPP color (logo) printed film in&nbsp;cutting sheets ( pages)